import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

export function PayPage() {
  const [selectedOption, setSelectedOption] = useState(null);
  const navigate = useNavigate();

  const options = [
    { id: 1, name: '뼈다귀 10개', price: 1900 },
    { id: 2, name: '뼈다귀 30개', price: 5900 },
    { id: 3, name: '뼈다귀 50개', price: 9900 },
  ];

  const handleProceedToCheckout = () => {
    if (!selectedOption) {
      alert('상품을 선택해주세요!');
      return;
    }

    // 선택한 상품 데이터를 Checkout 페이지로 전달
    navigate('/payment', { state: { selectedOption } });
  };

  return (
    <div>
      <h1>상품 선택</h1>
      <ul>
        {options.map((option) => (
          <li key={option.id}>
            <label>
              <input
                type="radio"
                name="product"
                value={option.id}
                onChange={() => setSelectedOption(option)}
              />
              {option.name} - {option.price.toLocaleString()}원
            </label>
          </li>
        ))}
      </ul>
      <button onClick={handleProceedToCheckout}>결제 진행</button>
    </div>
  );
}
